import static org.junit.Assert.assertEquals;

public class DurationFormatUtils_formatPeriod_TriageGen5Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");

















    @Test
    public void testFormatPeriod_NegativeAdjustments() {
        // This test targets the while(milliseconds < 0) etc. loops
        // By setting end time slightly "before" start time in terms of component fields
        // e.g., Start at 10:00:59, End at 11:00:01
        Calendar cal = Calendar.getInstance(GMT);
        cal.set(2023, Calendar.JANUARY, 1, 10, 0, 59);
        long start = cal.getTimeInMillis();

        cal.set(2023, Calendar.JANUARY, 1, 11, 0, 1);
        long end = cal.getTimeInMillis();

        // The difference is 2 seconds.
        // Component-wise: 
        // seconds: 1 - 59 = -58 -> loop: -58 + 60 = 2, minutes = 1 - 1 = 0
        // minutes: 0 - 0 = 0
        // hours: 11 - 10 = 1. But we must ensure the reduceAndCorrect logic doesn't break it.
        String result = DurationFormatUtils.formatPeriod(start, end, "s 's'", false, GMT);
        assertEquals("2s", result);
    }




}

