package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.TimeZone;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class DurationFormatUtils_formatPeriod_TriageGen5Test {

    private static final TimeZone GMT = TimeZone.getTimeZone("GMT");
    private static final TimeZone EST = TimeZone.getTimeZone("EST");





















    @Test
    public void testFormatPeriod_TimezoneDifferentiation() {
        // Test that timezone affects the Calendar calculation
        // Start: 2023-01-01 00:00:00 UTC
        // End: 2023-01-01 01:00:00 UTC
        // In GMT, this is 1 hour.
        // In a timezone that is 2 hours ahead (like AEST), the local hour might change, 
        // but the duration logic uses the absolute millis. 
        // However, the Calendar.getInstance(timezone) will pick up local components.

        long start = 1672531200000L; // 2023-01-01 00:00:00 GMT
        long end = 1672534800000L;   // 2023-01-01 01:00:00 GMT

        String resGmt = DurationFormatUtils.formatPeriod(start, end, "H", false, GMT);
        String resEst = DurationFormatUtils.formatPeriod(start, end, "H", false, EST);

        // The absolute duration is 1 hour.
        // In GMT: hour is 1.
        // In EST (GMT-5): start is 19:00 prev day, end is 20:00 prev day. Hour diff is 1.
        assertEquals("1", resGmt);
        assertEquals("1", resEst);
    }
}
